function drawTile(x,y,n,d,p) {
  n--;
  if (n){
    drawTile(x,y,n,d/2,p);
    drawTile(x+d/2,y,n,d/2,p);
    drawTile(x,y+d/2,n,d/2,p);
    drawTile(x+d/2,y+d/2,n,d/2,p);
  }else {
    const nScl = 0.01;
    const scl = 80;
    let l = random([15,20,25]);
    let n = noise(x*nScl,y*nScl)*scl;
    if (n>30) stroke(color(random(col1))); else stroke(color(random(col2)));
    if (n<40) l=random([2,3,5]);
    for(let i=0;i<12;i++) {
			switch(p) {
				case 2:strokeWeight(6);for(let j=0;j<6;j++)goPointGo(x,y,scl,nScl,l);break;
				case 3:strokeWeight(4);for(let j=0;j<2;j++)goPointGo(x,y,scl,nScl,l);break;
				case 4:strokeWeight(2);goPointGo(x,y,scl,nScl,l);break;
				case 5:strokeWeight(1);goPointGo(x,y,scl,nScl,l);break;
			}
		}
  }
}



function goPointGo(x,y,scl,nScl,l) {
  let n = noise(x*nScl,y*nScl)*scl;
  let prevX = x-n;
  let prevY = y-n;
  for (let i=0; i<l; i++) {
		if (dist(x,y,200,200)<200) {
			x+=cos(noise(x*nScl,y*nScl)*TWO_PI)*5;
			y+=sin(noise(x*nScl,y*nScl)*TWO_PI)*5;
			n = noise(x*nScl,y*nScl)*scl;
			line(prevX,prevY, prevX=x-n, prevY=y-n);
		}
  }
}




